"use strict";

var _util = require("./util");

/* eslint-env jest */
describe('isString', function () {
  it('returns true if the argument is a string', function () {
    expect((0, _util.isString)('42')).toBe(true);
    expect((0, _util.isString)(String('hello'))).toBe(true);
  });
  it('returns false if the argument is not a string', function () {
    expect((0, _util.isString)(42)).toBe(false);
    expect((0, _util.isString)({
      foo: 'bar'
    })).toBe(false);
    expect((0, _util.isString)(['foo'])).toBe(false);
  });
});